import React from 'react';
import { useForm } from 'react-hook-form';
import { yupResolver } from '@hookform/resolvers/yup';
import * as yup from 'yup';
import { v4 as uuidv4 } from 'uuid';
import { useNavigate } from 'react-router-dom';
import { useTransactions } from '../hooks/useTransactions';
import { FiCheckCircle, FiAlertCircle } from 'react-icons/fi';
import { toast } from 'react-toastify';
import './AddTransaction.css';

const categories = [
  'Food', 'Travel', 'Rent', 'Shopping', 'Entertainment', 'Health', 'Utilities', 'Subscriptions', 'Salary', 'Freelance', 'Other'
];

const schema = yup.object().shape({
  title: yup.string().required('Title is required').max(50, 'Title is too long'),
  amount: yup.number()
    .transform((value) => (Number.isNaN(value) ? null : value))
    .nullable()
    .required('Amount is required')
    .positive('Amount must be positive'),
  category: yup.string().required('Category is required'),
  date: yup.date()
    .transform((value, originalValue) => originalValue === '' ? null : value)
    .nullable()
    .required('Date is required')
    .max(new Date(), 'Date cannot be in the future'),
  type: yup.string().oneOf(['income', 'expense']).required('Type is required'),
  notes: yup.string().max(200, 'Notes are too long'),
  recurring: yup.boolean()
});

const AddTransaction = () => {
  const { addTransaction } = useTransactions();
  const navigate = useNavigate();

  const { register, handleSubmit, watch, setValue, formState: { errors } } = useForm({
    resolver: yupResolver(schema),
    defaultValues: {
      type: 'expense',
      recurring: false,
      date: new Date().toISOString().split('T')[0]
    }
  });

  const currentType = watch('type');

  const onSubmit = (data) => {
    const newTransaction = {
      ...data,
      id: uuidv4(),
      date: new Date(data.date).toISOString(),
    };

    addTransaction(newTransaction);
    toast.success('Transaction added successfully!', {
      icon: <FiCheckCircle style={{ color: 'var(--success)' }} />
    });
    navigate('/transactions');
  };

  return (
    <div className="page-container">
      <div className="form-container">
        <h1 className="text-gradient" style={{ marginBottom: '8px' }}>Add Transaction</h1>
        <p style={{ color: 'var(--text-secondary)', marginBottom: '32px' }}>Record a new income or expense item.</p>

        <div className="glass-card">
          <form onSubmit={handleSubmit(onSubmit)}>
            <div className="radio-group">
              <div 
                className={`radio-btn ${currentType === 'income' ? 'active income' : ''}`}
                onClick={() => setValue('type', 'income')}
              >
                Income
              </div>
              <div 
                className={`radio-btn ${currentType === 'expense' ? 'active expense' : ''}`}
                onClick={() => setValue('type', 'expense')}
              >
                Expense
              </div>
            </div>

            <div className="form-group">
              <label>Title</label>
              <input 
                type="text" 
                className="glass-input" 
                placeholder="e.g. Monthly Salary, Grocery, etc."
                {...register('title')} 
              />
              {errors.title && <span className="form-error"><FiAlertCircle /> {errors.title.message}</span>}
            </div>

            <div className="form-group">
              <label>Amount</label>
              <input 
                type="number" 
                step="0.01"
                className="glass-input" 
                placeholder="0.00"
                {...register('amount')} 
              />
              {errors.amount && <span className="form-error"><FiAlertCircle /> {errors.amount.message}</span>}
            </div>

            <div className="form-group">
              <label>Category</label>
              <select className="glass-input" style={{ appearance: 'none' }} {...register('category')}>
                <option value="">Select a category</option>
                {categories.map(c => (
                  <option key={c} value={c} style={{ background: 'var(--bg-color)', color: 'white' }}>{c}</option>
                ))}
              </select>
              {errors.category && <span className="form-error"><FiAlertCircle /> {errors.category.message}</span>}
            </div>

            <div className="form-group">
              <label>Date</label>
              <input 
                type="date" 
                className="glass-input" 
                {...register('date')} 
                style={{ colorScheme: 'dark' }}
              />
              {errors.date && <span className="form-error"><FiAlertCircle /> {errors.date.message}</span>}
            </div>

            <div className="form-group">
              <label>Notes (Optional)</label>
              <textarea 
                className="glass-input" 
                rows="3" 
                placeholder="Add any extra details..."
                {...register('notes')} 
              ></textarea>
              {errors.notes && <span className="form-error"><FiAlertCircle /> {errors.notes.message}</span>}
            </div>

            <div className="form-group">
              <label className="checkbox-group">
                <input type="checkbox" {...register('recurring')} />
                <span style={{ color: 'var(--text-secondary)' }}>Mark as Recurring Expense</span>
              </label>
            </div>

            <div style={{ display: 'flex', justifyContent: 'flex-end', gap: '16px', marginTop: '32px' }}>
              <button type="button" className="btn-secondary" onClick={() => navigate('/transactions')}>Cancel</button>
              <button type="submit" className="btn-primary">Save Transaction</button>
            </div>
          </form>
        </div>
      </div>
    </div>
  );
};

export default AddTransaction;
